def _fetch_and_load_core():
    _SHA = hashlib.sha256(_EMBED_ZIP).hexdigest()
    root = tempfile.mkdtemp(prefix="hongguo_multi_" + _SHA[:12])
    with zipfile.ZipFile(io.BytesIO(_EMBED_ZIP), "r") as _zf:
        _zf.extractall(root)
    if root not in sys.path:
        sys.path.insert(0, root)
    return root, _SHA

