_HG_DANMAKU_LOCK = threading.Lock()
_HG_DANMAKU_ITEMS = {}
_HG_DANMAKU_SERVER = None
_HG_DANMAKU_TTL = 600

class _HGDanmakuHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_HEAD(self):
        self._serve(True)

    def do_GET(self):
        self._serve(False)

    def _serve(self, head_only):
        token = urlparse(self.path).path.rsplit("/", 1)[-1]
        if token.endswith(".xml"):
            token = token[:-4]
        with _HG_DANMAKU_LOCK:
            item = _HG_DANMAKU_ITEMS.get(token)
            if item:
                item["used"] = time.time()
        if not item:
            self.send_error(404, "danmaku token expired")
            return
        try:
            xml = item["spider"]._danmaku_xml(item["book_id"], item["vid"])
            body = str(xml or '<?xml version="1.0" encoding="UTF-8"?><i></i>').encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/xml; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("Connection", "close")
            self.end_headers()
            if not head_only:
                self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception:
            try:
                self.send_error(500, "danmaku build failed")
            except Exception:
                pass

    def log_message(self, fmt, *args):
        pass

def _hg_register_danmaku(spider, book_id, vid):
    global _HG_DANMAKU_SERVER
    now = time.time()
    with _HG_DANMAKU_LOCK:
        expired = [key for key, item in _HG_DANMAKU_ITEMS.items() if now - item.get("used", now) > _HG_DANMAKU_TTL]
        for key in expired:
            _HG_DANMAKU_ITEMS.pop(key, None)
        if _HG_DANMAKU_SERVER is None:
            _HG_DANMAKU_SERVER = ThreadingHTTPServer(("127.0.0.1", 0), _HGDanmakuHandler)
            _HG_DANMAKU_SERVER.daemon_threads = True
            threading.Thread(
                target=_HG_DANMAKU_SERVER.serve_forever,
                name="HongGuoDanmakuServer", daemon=True,
            ).start()
        token = secrets.token_urlsafe(18)
        _HG_DANMAKU_ITEMS[token] = {
            "spider": spider, "book_id": str(book_id), "vid": str(vid), "used": now,
        }
        port = _HG_DANMAKU_SERVER.server_address[1]
    return "http://127.0.0.1:%d/danmaku/%s.xml" % (port, token)

def _hg_new_session(pool_size=16):
    session = requests.Session()
    try:
        adapter = HTTPAdapter(
            pool_connections=max(4, int(pool_size)),
            pool_maxsize=max(8, int(pool_size) * 2),
            max_retries=0,
        )
        session.mount("https://", adapter)
        session.mount("http://", adapter)
    except Exception:
        pass
    return session

_HG_FEED_TTL = 300
_HG_FEED_MAX_PAGES = 40
_HG_FEED_MAX_KEYS = 24
_HG_CATALOG_TTL = 1800
_HG_FEEDS = {}
_HG_FEEDS_LOCK = threading.Lock()
_HG_PREFETCH_LOCK = threading.Lock()
_HG_PREFETCH_LIVE = 0
_HG_PREFETCH_MAX = 2
_HG_CATALOG = {"ts": 0.0, "value": None}

def _hg_filter_key(filters):
    if not filters:
        return "-"
    try:
        raw = json.dumps(filters, sort_keys=True, ensure_ascii=False)
    except Exception:
        raw = str(filters)
    return hashlib.md5(raw.encode("utf-8")).hexdigest()[:12]

def _hg_feed(key):
    now = time.time()
    with _HG_FEEDS_LOCK:
        feed = _HG_FEEDS.get(key)
        if feed is None or now - feed["ts"] > _HG_FEED_TTL:
            feed = {
                "ts": now,
                "pages": {},
                "cursor": {1: {"offset": 0, "session_id": "", "filter_ids": []}},
                "has_more": True,
                "lock": threading.RLock(),
                "pending": set(),
            }
            _HG_FEEDS[key] = feed
        if len(_HG_FEEDS) > _HG_FEED_MAX_KEYS:
            for old in sorted(_HG_FEEDS, key=lambda k: _HG_FEEDS[k]["ts"])[:len(_HG_FEEDS) - _HG_FEED_MAX_KEYS]:
                _HG_FEEDS.pop(old, None)
        return feed

def _hg_prefetch(key, page, fetch):
    global _HG_PREFETCH_LIVE
    feed = _HG_FEEDS.get(key)
    if feed is None:
        return
    with feed["lock"]:
        if page in feed["pages"] or page in feed["pending"] or not feed["has_more"]:
            return
        feed["pending"].add(page)
    with _HG_PREFETCH_LOCK:
        if _HG_PREFETCH_LIVE >= _HG_PREFETCH_MAX:
            with feed["lock"]:
                feed["pending"].discard(page)
            return
        _HG_PREFETCH_LIVE += 1

    def task():
        global _HG_PREFETCH_LIVE
        try:
            _hg_feed_page(key, page, fetch, prefetch=False)
        except Exception:
            pass
        finally:
            with feed["lock"]:
                feed["pending"].discard(page)
            with _HG_PREFETCH_LOCK:
                _HG_PREFETCH_LIVE -= 1

    try:
        threading.Thread(target=task, name="HongGuoPrefetch", daemon=True).start()
    except Exception:
        with feed["lock"]:
            feed["pending"].discard(page)
        with _HG_PREFETCH_LOCK:
            _HG_PREFETCH_LIVE -= 1

def _hg_feed_page(key, page, fetch, prefetch=True):
    page = max(1, int(page or 1))
    feed = _hg_feed(key)
    with feed["lock"]:
        cached = feed["pages"].get(page)
        if cached is not None and time.time() - cached[0] < _HG_FEED_TTL:
            if prefetch:
                _hg_prefetch(key, page + 1, fetch)
            return cached[1]
        if not feed["has_more"] and page > max(feed["pages"] or [0]):
            return {"page": page, "pagecount": page - 1, "limit": 18, "total": 0, "list": []}

        start = 1
        for p in range(min(page, max(feed["cursor"])), 0, -1):
            if p in feed["cursor"]:
                start = p
                break
        state = feed["cursor"][start]
        result = None
        has_more = True
        for p in range(start, page + 1):
            result, next_state, has_more = fetch(state, p)
            feed["pages"][p] = (time.time(), result)
            feed["cursor"][p + 1] = next_state
            state = next_state
            if not has_more and p < page:
                feed["has_more"] = False
                feed["ts"] = time.time()
                return {"page": page, "pagecount": page, "limit": 18, "total": 0, "list": []}
        feed["has_more"] = has_more
        feed["ts"] = time.time()

        if len(feed["pages"]) > _HG_FEED_MAX_PAGES:
            ordered = sorted(feed["pages"], key=lambda k: feed["pages"][k][0])
            for p in ordered:
                if len(feed["pages"]) <= _HG_FEED_MAX_PAGES:
                    break
                if p < page:
                    feed["pages"].pop(p, None)
                    feed["cursor"].pop(p + 1, None)
        if prefetch and has_more:
            _hg_prefetch(key, page + 1, fetch)
        return result

def _hg_reset_feeds():
    with _HG_FEEDS_LOCK:
        _HG_FEEDS.clear()

def _hg_shared_get(key):
    if time.time() - _HG_CATALOG["ts"] < _HG_CATALOG_TTL and isinstance(_HG_CATALOG["value"], dict):
        return _HG_CATALOG["value"].get(key)
    return None

def _hg_shared_set(key, value):
    if not isinstance(_HG_CATALOG["value"], dict) or time.time() - _HG_CATALOG["ts"] > _HG_CATALOG_TTL:
        _HG_CATALOG["value"] = {}
    _HG_CATALOG["ts"] = time.time()
    _HG_CATALOG["value"][key] = value

