    class _LRUCache:
        def __init__(self, maxsize=200, ttl=600):
            self.maxsize = maxsize
            self.ttl = ttl
            self._data = {}
            self._order = []

        def get(self, key):
            if key not in self._data:
                return None
            entry = self._data[key]
            data, timestamp = entry[0], entry[1]
            ttl = entry[2] if len(entry) > 2 and entry[2] else self.ttl
            if time.time() - timestamp > ttl:
                self._remove(key)
                return None
            self._order.remove(key)
            self._order.append(key)
            return data

        def set(self, key, value, ttl=None):
            if key in self._data:
                self._remove(key)
            elif len(self._data) >= self.maxsize:
                oldest = self._order.pop(0)
                del self._data[oldest]
            self._data[key] = (value, time.time(), ttl)
            self._order.append(key)

        def _remove(self, key):
            if key in self._data:
                del self._data[key]
                self._order.remove(key)

        def clear(self):
            self._data.clear()
            self._order.clear()

    APP_TIMEOUT = (4, 12)
    APP_RETRIES = 2

    def __init__(self):
        self._cache = self._LRUCache(maxsize=200, ttl=600)
        self._video_cache = self._LRUCache(maxsize=20, ttl=300)
        self._catalog_cache = self._LRUCache(maxsize=12, ttl=_HG_CATALOG_TTL)
        self._actor_cache = self._LRUCache(maxsize=80, ttl=180)
        self._danmaku_cache = self._LRUCache(maxsize=120, ttl=300)
        self._danmaku_building = set()
        self._app_item_cache = {}
        self._series_item_cache = {}
        self._episode_book_cache = {}
        self._video_lock = threading.Lock()
        self._danmaku_lock = threading.Lock()
        self.session = _hg_new_session(8)
        self._app_session = _hg_new_session(16)

