    def _get(self, url, retries=3):
        last_exc = None
        for attempt in range(1, max(1, int(retries)) + 1):
            try:
                response = self.session.get(url, headers=self.headers, timeout=(4, 15))
                if response.status_code >= 500:
                    raise requests.HTTPError("HTTP %s" % response.status_code)
                response.raise_for_status()
                response.encoding = "utf-8"
                return response.text
            except Exception as exc:
                last_exc = exc
                if attempt < retries:
                    time.sleep(0.15 * attempt)
        raise last_exc

    def _extract_json(self, html):
        p = html.find("_ROUTER_DATA = ")
        if p < 0:
            p = html.find("window._ROUTER_DATA = ")
        if p < 0:
            raise RuntimeError("_ROUTER_DATA not found")
        p = html.find("{", p)
        if p < 0:
            raise RuntimeError("No JSON object found")
        depth = 0
        in_string = False
        escape = False
        i = p
        while i < len(html):
            c = html[i]
            if escape:
                escape = False
            elif c == '\\':
                escape = True
            elif c == '"':
                in_string = not in_string
            elif not in_string:
                if c == '{':
                    depth += 1
                elif c == '}':
                    depth -= 1
                    if depth == 0:
                        break
            i += 1
        if depth != 0:
            raise RuntimeError("Unbalanced JSON")
        return json.loads(html[p:i+1])

    def _router_data(self, url, retries=3):
        cached = self._cache.get(url)
        if cached is not None:
            return cached
        last_exc = None
        for attempt in range(1, max(1, int(retries)) + 1):
            try:
                html = self._get(url, retries=1)
                match = re.search(r"(?:window\.)?_ROUTER_DATA\s*=\s*", html)
                if not match:
                    raise RuntimeError("_ROUTER_DATA not found")
                data, _ = json.JSONDecoder().raw_decode(html, match.end())
                self._cache.set(url, data)
                return data
            except Exception as exc:
                last_exc = exc
                if attempt < retries:
                    time.sleep(0.45 * attempt)
        raise last_exc

    @staticmethod
    def _app_bool(value):
        if isinstance(value, str):
            return value.lower() not in ("", "0", "false", "no")
        return bool(value)

    @staticmethod
    def _safe_name(value):
        return str(value or "").replace("$", " ").replace("#", " ").strip()

    @staticmethod
    def _encode_play_id(book_id, vid, quality):
        payload = json.dumps(
            [str(book_id or ""), str(vid or ""), str(quality or "auto")],
            ensure_ascii=True, separators=(",", ":"),
        ).encode("utf-8")
        return "hgplay_" + _b64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    @staticmethod
    def _decode_play_id(value):
        raw = html.unescape(str(value or "")).strip()
        for _ in range(2):
            decoded = unquote(raw)
            if decoded == raw:
                break
            raw = decoded
        if "$" in raw:
            raw = raw.rsplit("$", 1)[-1].strip()
        if raw.startswith("hgplay_"):
            token = raw[len("hgplay_"):]
            try:
                values = json.loads(_b64.urlsafe_b64decode(token + "=" * (-len(token) % 4)).decode("utf-8"))
                if isinstance(values, list) and len(values) >= 3:
                    return str(values[0]), str(values[1]), str(values[2] or "auto")
            except Exception:
                return "", "", "auto"
        parts = raw.split("|")
        if len(parts) >= 3:
            return parts[0], parts[1], parts[2]
        return "", parts[0] if parts else "", parts[1] if len(parts) > 1 else "auto"

    @classmethod
    def _app_params(cls, values=None):
        params = dict(cls.APP_DEVICE)
        if isinstance(values, dict):
            params.update({str(k): str(v) for k, v in values.items() if v is not None})
        return params

    def _signed_app_request(self, method, url, values=None, payload=None, retries=None, xs_from_web="1", anniex_prefetch="1"):
        from flurl.core import core_sixgod

        retries = self.APP_RETRIES if retries is None else retries
        method = str(method or "GET").upper()
        body_obj = payload if isinstance(payload, dict) else {}
        body_text = json.dumps(body_obj, ensure_ascii=False, separators=(",", ":")) if method == "POST" else ""
        last_exc = None
        for attempt in range(max(1, int(retries))):
            ticket = str(int(time.time() * 1000))
            params = self._app_params(values)
            params["_rticket"] = ticket
            headers = {
                "User-Agent": self.APP_UA,
                "Accept": "application/json; charset=utf-8,application/x-protobuf",
                "Accept-Encoding": "gzip",
                "x-xs-from-web": str(xs_from_web),
                "anniex-prefetch": str(anniex_prefetch),
                "x-ss-req-ticket": ticket,
                "x-vc-bdturing-sdk-version": "4.0.3.cn",
                "authorization": "Bearer",
                "lc": "101",
                "sdk-version": "2",
                "passport-sdk-version": "5051452",
                "x-tt-store-region": "cn-js",
                "x-tt-store-region-src": "did",
                "x-tt-request-tag": "t=0;n=0",
            }
            if method == "POST":
                headers["Content-Type"] = "application/json; charset=UTF-8"
                headers["comment-source"] = str(body_obj.get("comment_source") or 601)
                headers["server-channel"] = str(body_obj.get("server_channel") or 1000)
                headers["s-trace-span-id"] = str(1000000000000000 + time.time_ns() % 9000000000000000)
            else:
                headers["x-reading-request"] = ticket + "-" + str(time.time_ns() % 2000000000)
            devices = {
                "device_id": params.get("device_id", ""),
                "iid": params.get("iid", ""),
                "install_id": params.get("iid", ""),
                "device_brand": params.get("device_brand", "HONOR"),
                "device_model": params.get("device_type", "BVL-AN00"),
                "device_type": params.get("device_type", "BVL-AN00"),
                "device_manufacturer": params.get("device_brand", "HONOR"),
                "os_version": params.get("os_version", "12"),
                "version_name": params.get("version_name", "7.3.5.32"),
                "ua": self.APP_UA,
            }
            try:
                signed_headers, signed_url = core_sixgod(
                    surl=url, params=params, data=body_obj if method == "POST" else {},
                    devices=devices, header=headers, log=False,
                )
                response = self._app_session.request(
                    method, signed_url, headers=signed_headers,
                    data=body_text.encode("utf-8") if method == "POST" else None,
                    timeout=self.APP_TIMEOUT,
                )
                if response.status_code == 429 or response.status_code >= 500:
                    raise requests.HTTPError("HTTP %s" % response.status_code)
                response.raise_for_status()
                data = response.json()
                code = data.get("code", data.get("Code")) if isinstance(data, dict) else None
                if not isinstance(data, dict) or (code is not None and int(code or 0) != 0):
                    raise RuntimeError("App API 返回异常: %s" % str(data)[:300])
                return data
            except Exception as exc:
                last_exc = exc
                if attempt + 1 < max(1, int(retries)):
                    time.sleep(0.12 * (attempt + 1))
        raise last_exc

    def _signed_app_get(self, url, values, retries=None, xs_from_web="1", anniex_prefetch="1"):
        return self._signed_app_request("GET", url, values, None, retries, xs_from_web, anniex_prefetch)

    def _signed_app_post(self, url, values, payload, retries=None):
        return self._signed_app_request("POST", url, values, payload, retries)

    @staticmethod
    def _object_variants(value, depth=0, max_depth=5, output=None):
        output = [] if output is None else output
        if not isinstance(value, (dict, list)) or depth > max_depth or any(value is x for x in output):
            return output
        output.append(value)
        children = value.values() if isinstance(value, dict) else value
        for child in children:
            if isinstance(child, str):
                try:
                    child = json.loads(child)
                except Exception:
                    continue
            if isinstance(child, (dict, list)):
                Spider._object_variants(child, depth + 1, max_depth, output)
        return output

    @classmethod
    def _response_array(cls, data, keys):
        for value in cls._object_variants(data, max_depth=3):
            if not isinstance(value, dict):
                continue
            for key in keys:
                candidate = value.get(key)
                if isinstance(candidate, list):
                    return candidate
        return []

    VOD_STR_FIELDS = (
        "vod_id", "vod_name", "type_name", "vod_pic", "vod_remarks", "vod_year",
        "vod_area", "vod_director", "vod_actor", "vod_content", "vod_play_from",
        "vod_play_url", "vod_tag", "action",
    )
    STYLE_TYPES = ("rect", "oval", "list", "full")

    @staticmethod
    def _safe_float(value):
        try:
            number = float(value)
        except (TypeError, ValueError):
            return None
        if number != number or number in (float("inf"), float("-inf")):
            return None
        return number

    @staticmethod
    def _ok_int(value, default):
        try:
            return int(value or default)
        except (TypeError, ValueError):
            return default

    @classmethod
    def _ok_vod(cls, item):
        if not isinstance(item, dict):
            return None
        vod = {}
        for key in cls.VOD_STR_FIELDS:
            value = item.get(key)
            if value is None or isinstance(value, (dict, list, tuple, set)):
                continue
            if isinstance(value, bool):
                value = "1" if value else ""
            elif isinstance(value, float) and cls._safe_float(value) is None:
                continue
            text = str(value)
            if text:
                vod[key] = text
        if not vod.get("vod_id") or not vod.get("vod_name"):
            return None
        vod["vod_id"] = str(vod["vod_id"])
        vod.setdefault("vod_pic", "")
        vod.setdefault("vod_remarks", "")
        style = item.get("style")
        if isinstance(style, dict):
            style_type = str(style.get("type") or "rect")
            clean = {"type": style_type if style_type in cls.STYLE_TYPES else "rect"}
            ratio = cls._safe_float(style.get("ratio"))
            if ratio and ratio > 0:
                clean["ratio"] = min(ratio, 4.0)
            vod["style"] = clean
        extra = item.get("vod_extra")
        if isinstance(extra, dict):
            try:
                json.dumps(extra)
                vod["vod_extra"] = extra
            except (TypeError, ValueError):
                pass
        return vod

    @classmethod
    def _ok_result(cls, result, limit=18, page=1):
        result = result if isinstance(result, dict) else {}
        page = max(1, cls._ok_int(result.get("page"), page))
        rows = result.get("list")
        items = [v for v in (cls._ok_vod(r) for r in rows or []) if v] if isinstance(rows, (list, tuple)) else []
        return {
            "page": page,
            "pagecount": max(page, cls._ok_int(result.get("pagecount"), page)),
            "limit": max(1, cls._ok_int(limit, 18)),
            "total": max(cls._ok_int(result.get("total"), 0), len(items)),
            "list": items,
        }

    @classmethod
    def _ok_filters(cls, filters):
        if not isinstance(filters, dict):
            return {}
        clean = {}
        for type_id, rows in filters.items():
            if not isinstance(rows, (list, tuple)):
                continue
            entries = [r for r in rows if isinstance(r, dict) and r.get("key") and r.get("value")]
            if entries:
                clean[str(type_id)] = entries
        return clean

    def _app_vod(self, item):
        source = item.get("video_data") if isinstance(item, dict) and isinstance(item.get("video_data"), dict) else item
        source = source if isinstance(source, dict) else {}
        sid = str(source.get("series_id") or source.get("seriesId") or source.get("book_id") or source.get("bookId") or "")
        name = self._safe_name(source.get("series_name") or source.get("series_title") or source.get("seriesTitle") or source.get("title") or source.get("book_name") or source.get("name"))
        pic = str(source.get("series_cover") or source.get("cover") or source.get("cover_url") or "").replace("\\/", "/")
        episode_info = source.get("series_episode_info") or {}
        try:
            count = int(source.get("episode_cnt") or (episode_info.get("episode_cnt") if isinstance(episode_info, dict) else 0) or 0)
        except (TypeError, ValueError):
            count = 0
        categories = source.get("category_list") or []
        tags = source.get("tags") or []
        labels = []
        tag_values = tags if isinstance(tags, list) else [tags]
        category_values = categories if isinstance(categories, list) else [categories]
        for value in tag_values + category_values:
            if isinstance(value, dict):
                value = value.get("name") or value.get("content")
            if value:
                labels.append(str(value))
        badge = self._extract_badge(source)
        collection = self._extract_collection(source)
        rec_text = self._extract_rec_text(source)
        actor = self._extract_actors(source)
        if sid and source.get("vid_list"):
            self._series_item_cache[sid] = source
        if sid:
            self._app_item_cache[sid] = source
        return {
            "vod_id": sid,
            "vod_name": name,
            "vod_pic": pic,
            "vod_remarks": str(source.get("episode_right_text") or ("全%d集" % count if count else "")),
            "vod_year": badge,
            "vod_actor": actor,
            "type_name": "/".join(labels[:5]),
            "vod_content": str(source.get("series_intro") or source.get("video_desc") or source.get("description") or ""),
            "vod_extra": {
                "badge": badge,
                "collection": collection,
                "rec_text": rec_text,
            },
        }

    def _panel_filters(self, panel, include_genre=False):
        result = []
        rows = panel.get("selector_rows") if isinstance(panel, dict) else []
        for row in rows if isinstance(rows, list) else []:
            row_type = str(row.get("type") or "")
            if row_type == "genre" and not include_genre:
                continue
            key = self.PANEL_FILTER_KEY.get(row_type)
            if not key:
                continue
            values = []
            for item in row.get("items") or []:
                name = str(item.get("show_name") or "").strip()
                value = str(item.get("selector_item_id") or "").strip()
                if name and value:
                    values.append({"n": name, "v": value})
            if values:
                name = str(row.get("row_name") or key)
                result.append({"key": key, "name": name, "value": [{"n": name or "全部", "v": ""}] + values})
        return result

    def _distribution_panel(self, scene):
        data = self._signed_app_post(
            self.APP_DISTRIBUTION_API,
            {"need_selector_panel": "false", "req_type": "only_panel", "req_scene": scene},
            {"req_scene": scene, "need_selector_panel": False, "req_type": "only_panel"},
        )
        return data.get("data") or data.get("Data") or {}

