    @classmethod
    def _rank_selector_items(cls, node):
        if not isinstance(node, dict):
            return []
        items = (node.get("outer_row") or {}).get("items")
        return [x for x in items if isinstance(x, dict)] if isinstance(items, list) else []

    def _rank_catalog(self):
        cached = self._catalog_cache.get("rank_catalog") or _hg_shared_get("rank_catalog")
        if cached is not None:
            return cached
        try:
            items = self._rank_selector_items(
                ((self._rank_request("all").get("data") or {}).get("cell_view") or {}).get("cell_selector"))
        except Exception:
            items = []

        def pick(node):
            return (str(node.get("selector_item_id") or "").strip(),
                    str(node.get("show_name") or "").strip(),
                    str(node.get("title_url") or node.get("dark_title_url") or ""))

        groups = []
        for item in items:
            selected, name, pic = pick(item)
            if not selected or not name or selected == "ranklist_celebrity":
                continue
            subs = [{"selected": s, "name": n, "pic": p}
                    for s, n, p in (pick(x) for x in self._rank_selector_items(item.get("sub_cell_selector")))
                    if s and n]
            groups.append({"selected": selected, "name": name, "pic": pic,
                           "sub": subs or [{"selected": "", "name": name, "pic": pic}]})
        value = {"groups": groups}
        self._catalog_cache.set("rank_catalog", value, ttl=20 if not groups else _HG_CATALOG_TTL)
        if groups:
            _hg_shared_set("rank_catalog", value)
        return value

    def _actor_filters(self):
        return [{"key": "rank", "name": "榜单", "value": [
            {"n": item["type_name"], "v": item["type_id"]} for item in self.ACTOR_RANK_CONFIG
        ]}]

    def _catalog(self):
        cached = self._catalog_cache.get("catalog") or _hg_shared_get("catalog")
        if cached is not None:
            return cached
        scenes = ("short_play", "comic_series", "ai_series")
        panels = {}
        with ThreadPoolExecutor(max_workers=4) as executor:
            future_to_scene = {
                executor.submit(self._distribution_panel, scene): scene
                for scene in scenes
            }
            future_rank = executor.submit(self._rank_catalog)

            for future in future_to_scene:
                scene = future_to_scene[future]
                try:
                    panels[scene] = future.result()
                except Exception:
                    panels[scene] = {}

            try:
                ranks = future_rank.result()
            except Exception:
                ranks = {"groups": []}

        classes = list(self.CLASS_LIST)
        filters = {
            "short_play": self._panel_filters(panels.get("short_play") or {}),
            "comic_series": self._panel_filters(panels.get("comic_series") or {}),
            "ai_series": self._panel_filters(panels.get("ai_series") or {}),
            "new_series": [
                item for item in self._panel_filters(panels.get("short_play") or {})
                if item.get("key") in ("recommend", "audience")
            ],
            "rank_home": [],
            "actor_home": self._actor_filters(),
        }
        value = {"class": classes, "filters": filters, "ranks": ranks}
        ttl = 20 if not ranks.get("groups") else _HG_CATALOG_TTL
        self._catalog_cache.set("catalog", value, ttl=ttl)
        if ranks.get("groups"):
            _hg_shared_set("catalog", value)
        return value

    @staticmethod
    def _filter_values(value):
        if isinstance(value, dict):
            result = {}
            for key, item in value.items():
                if key == "filters":
                    continue
                if item not in (None, "", "-1"):
                    result[str(key)] = str(item)
            for item in value.get("filters") if isinstance(value.get("filters"), list) else []:
                key = str(item.get("key") or "")
                selected = item.get("init")
                if selected in (None, ""):
                    for option in item.get("value") or []:
                        if option.get("v") not in (None, "", "-1"):
                            selected = option.get("v")
                            break
                if key and selected not in (None, "", "-1"):
                    result[key] = str(selected)
            return result
        if not isinstance(value, str) or not value.strip():
            return {}
        candidates = [value]
        try:
            candidates.append(unquote(value))
        except Exception:
            pass
        try:
            candidates.append(_b64.b64decode(value + "=" * (-len(value) % 4)).decode("utf-8"))
        except Exception:
            pass
        for candidate in candidates:
            try:
                parsed = json.loads(candidate)
                if isinstance(parsed, dict):
                    return Spider._filter_values(parsed)
            except Exception:
                pass
            query = dict(parse_qsl(candidate, keep_blank_values=True))
            if query:
                return Spider._filter_values(query)
        return {}

    @staticmethod
    def _bookmall_list(data):
        candidates = [
            ((data.get("data") or {}).get("cell_view") if isinstance(data.get("data"), dict) else None),
            data.get("data"), data.get("Data"), (data.get("data") or {}).get("data") if isinstance(data.get("data"), dict) else None,
            data.get("result"), data,
        ]
        for value in candidates:
            if not isinstance(value, dict):
                continue
            for key in ("video_data", "cell_data", "cellData", "book_list", "books", "items", "list"):
                if isinstance(value.get(key), list):
                    return value[key]
        return []

    @staticmethod
    def _is_short_drama(video):
        if not isinstance(video, dict):
            return False
        try:
            content_type = int(video.get("content_type"))
        except (TypeError, ValueError):
            return False
        if content_type not in (1, 1004):
            return False
        detail = video.get("video_detail", {})
        detail = detail if isinstance(detail, dict) else {}
        episode_count = video.get("episode_cnt") or detail.get("episode_cnt") or 0
        return bool(video.get("episode") is True or detail.get("episode") is True or episode_count)

    @staticmethod
    def _extract_collection(video):
        if not isinstance(video, dict):
            return ""
        detail = video.get("video_detail", {})
        detail = detail if isinstance(detail, dict) else {}
        rec_tags = video.get("rec_tags") or detail.get("rec_tags") or []
        for tag in rec_tags:
            if isinstance(tag, dict):
                content = tag.get("content", "")
                if "收藏" in content:
                    return content
        followed_cnt = video.get("followed_cnt") or detail.get("followed_cnt") or 0
        if followed_cnt:
            try:
                followed_cnt = float(followed_cnt)
                if followed_cnt >= 10000:
                    return f"{followed_cnt/10000:.1f}万收藏"
                return f"{int(followed_cnt)}收藏"
            except (TypeError, ValueError):
                pass
        subtitles = video.get("sub_title_list") or detail.get("sub_title_list") or []
        for subtitle in subtitles if isinstance(subtitles, list) else []:
            if not isinstance(subtitle, dict):
                continue
            content = str(subtitle.get("content") or "").strip()
            if content and str(subtitle.get("data_type") or "") == "27":
                return content
        return ""

    @staticmethod
    def _extract_badge(video):
        if not isinstance(video, dict):
            return ""
        detail = video.get("video_detail", {})
        detail = detail if isinstance(detail, dict) else {}
        for tag_info in (video.get("tag_info"), detail.get("tag_info")):
            if isinstance(tag_info, dict):
                badge = tag_info.get("text") or tag_info.get("content") or tag_info.get("title")
                if badge:
                    return str(badge)
        return Spider._extract_collection(video)

    @staticmethod
    def _extract_rec_text(video):
        if not isinstance(video, dict):
            return ""
        detail = video.get("video_detail", {})
        detail = detail if isinstance(detail, dict) else {}
        direct = video.get("rec_text") or video.get("sub_title") or detail.get("rec_text") or detail.get("sub_title")
        if direct:
            return str(direct)
        subtitles = video.get("sub_title_list") or detail.get("sub_title_list") or []
        values = []
        for subtitle in subtitles if isinstance(subtitles, list) else []:
            value = subtitle.get("content") if isinstance(subtitle, dict) else subtitle
            if value:
                values.append(str(value))
        return " · ".join(values)

    @staticmethod
    def _extract_actors(video):
        if not isinstance(video, dict):
            return ""
        names = []
        seen = set()

        def add_raw(raw):
            if isinstance(raw, str):
                for part in re.split(r'[,，、\s]+', raw.strip()):
                    part = part.strip()
                    if part and part not in seen:
                        seen.add(part)
                        names.append(part)
            elif isinstance(raw, list):
                for item in raw:
                    add_raw(item)
            elif isinstance(raw, dict):
                for key in ("nickname", "actor_name", "actorName", "celebrity_name",
                            "celebrityName", "user_name", "userName", "name"):
                    val = raw.get(key)
                    if isinstance(val, str) and val.strip():
                        add_raw(val)
                        return

        containers = [video]
        for key in ("video_detail", "series_detail", "seriesDetail", "book_info", "bookInfo"):
            val = video.get(key)
            if isinstance(val, dict):
                containers.append(val)

        actor_keys = ("vod_actor", "actor", "actors", "actor_list", "actorList",
                      "cast", "stars", "role", "roles", "celebrities", "celebrity_list", "celebrityList")
        for container in containers:
            for key in actor_keys:
                value = container.get(key)
                if value:
                    add_raw(value)

        return ",".join(names)

    def _vod(self, item):
        tags = item.get("tags") or []
        if isinstance(tags, list):
            tags = " · ".join(str(x) for x in tags[:3])
        count = item.get("episode_cnt") or len(item.get("vid_list") or [])
        badge = ""
        collection = ""
        actor = ""
        video_data = item.get("video_data", [])
        if video_data and isinstance(video_data, list):
            first_video = video_data[0]
            if isinstance(first_video, dict):
                badge = self._extract_badge(first_video)
                collection = self._extract_collection(first_video)
                actor = self._extract_actors(first_video)
        vod_remarks = f"全{count}集" if count else ""
        return {
            "vod_id": str(item.get("series_id") or ""),
            "vod_name": str(item.get("series_name") or ""),
            "vod_pic": str(item.get("series_cover") or ""),
            "vod_remarks": vod_remarks,
            "vod_year": badge,
            "vod_actor": actor,
        }

    @staticmethod
    def _distribution_select_items(scene, filters=None):
        selected = {
            "duration": [], "category_dim_epoch": [], "online_time": [], "gender": [],
            "category_dim_role": [], "genre": [scene], "creation_status": [], "sort": [],
            "category_dim_theme": [],
        }
        keys = {
            "background": "category_dim_epoch", "theme": "category_dim_theme",
            "setting": "category_dim_role", "recommend": "sort", "audience": "gender",
            "status": "creation_status", "time": "online_time", "duration": "duration",
        }
        for key, value in (filters or {}).items():
            if value in (None, "") or key == "cateId":
                continue
            target = keys.get(key, key)
            if target in selected:
                selected[target] = [str(x) for x in value] if isinstance(value, list) else [str(value)]
        return selected

    def _distribution_fetch(self, state, page, scene, filters):
        limit = 18
        payload = {
            "filter_ids": ",".join(state.get("filter_ids") or []), "req_scene": scene,
            "offset": state.get("offset") or 0,
            "need_selector_panel": False, "limit": limit,
            "select_items": self._distribution_select_items(scene, filters),
            "session_id": state.get("session_id") or "", "req_type": "only_content",
            "client_req_type": 3 if page == 1 else 2,
        }
        data = self._signed_app_post(
            self.APP_DISTRIBUTION_API,
            {"req_scene": scene, "need_selector_panel": "false", "req_type": "only_content"},
            payload,
        )
        root = data.get("data") or data.get("Data") or data or {}
        root = root if isinstance(root, dict) else {}
        raw = root.get("video_data")
        if not isinstance(raw, list):
            raw = self._response_array(data, ("video_data", "videos", "list", "items"))
        videos = []
        for item in raw:
            vod = self._app_vod(item)
            if vod["vod_id"] and vod["vod_name"]:
                videos.append(vod)
        has_more = self._app_bool(root.get("has_more"))
        offset = int(root.get("next_offset") or (state.get("offset") or 0) + limit)
        result = {
            "page": page, "pagecount": page + 1 if has_more else page,
            "limit": limit, "total": 0, "list": videos,
        }
        next_state = {
            "offset": offset,
            "session_id": str(root.get("session_id") or ""),
            "filter_ids": (state.get("filter_ids") or []) + [vod["vod_id"] for vod in videos],
        }
        return result, next_state, has_more

    def _distribution_page(self, scene, page, filters=None, prefetch=True):
        filters = filters or {}
        key = "dist|%s|%s" % (scene, _hg_filter_key(filters))

        def fetch(state, current):
            return self._distribution_fetch(state, current, scene, filters)

        return _hg_feed_page(key, page, fetch, prefetch=prefetch)

    def _new_fetch(self, state, page, filters):
        limit = 18
        data = self._signed_app_get(self.APP_BOOKMALL_API, {
            "book_type": "0", "cell_id": self.NEW_CELL_ID, "change_type": "1",
            "client_req_type": "0", "limit": str(limit), "offset": str(state.get("offset") or 0),
            "selected_items": filters.get("recommend") or "firstonlinetime_new",
            "session_id": state.get("session_id") or "", "cell_gender": filters.get("audience") or "2",
            "klink_egdi": self.APP_KLINK_EGDI,
        })
        root = data.get("data") or data.get("Data") or {}
        root = root if isinstance(root, dict) else {}
        videos = []
        for item in self._bookmall_list(data):
            source = item.get("video_data") or item.get("book_info") or item if isinstance(item, dict) else item
            vod = self._app_vod(source)
            if vod["vod_id"] and vod["vod_name"]:
                videos.append(vod)
        has_more = self._app_bool(root.get("has_more"))
        offset = int(root.get("next_offset") or (state.get("offset") or 0) + limit)
        result = {"page": page, "pagecount": page + 1 if has_more else page, "limit": limit, "total": 0, "list": videos}
        next_state = {"offset": offset, "session_id": str(root.get("session_id") or ""), "filter_ids": []}
        return result, next_state, has_more

    def _new_page(self, page, filters=None, prefetch=True):
        filters = filters or {}
        key = "new|%s" % _hg_filter_key({k: v for k, v in filters.items() if k in ("recommend", "audience")})

        def fetch(state, current):
            return self._new_fetch(state, current, filters)

        return _hg_feed_page(key, page, fetch, prefetch=prefetch)

    def _rank_page(self, ranks, page, filters=None):
        groups = ranks.get("groups") or []
        if not groups:
            return {"page": page, "pagecount": page, "limit": 18, "total": 0, "list": []}
        filters = filters or {}
        selected = str(filters.get("rank_category") or groups[0]["selected"])
        sub_selected = str(filters.get("rank") or "")
        if "|" in sub_selected:
            selected, sub_selected = sub_selected.split("|", 1)
        group = next((item for item in groups if item["selected"] == selected), groups[0])
        sub = next((item for item in group.get("sub") or [] if item["selected"] == sub_selected), None)
        if sub is None:
            sub = (group.get("sub") or [None])[0]
        if sub is None:
            return {"page": page, "pagecount": page, "limit": 18, "total": 0, "list": []}
        cache_key = "rank|%s|%s|%s" % (group["selected"], sub["selected"], page)
        cached = self._actor_cache.get(cache_key)
        if cached is not None:
            return cached
        limit = 18
        try:
            data = self._rank_request(group["selected"], sub["selected"], (page - 1) * limit, limit)
        except Exception:
            return {"page": page, "pagecount": page, "limit": limit, "total": 0, "list": []}
        cell_data = (((data.get("data") or {}).get("cell_view") or {}).get("cell_data") or [])
        raw = []
        for cell in cell_data if isinstance(cell_data, list) else []:
            if isinstance(cell, dict) and isinstance(cell.get("video_data"), list):
                raw.extend(cell["video_data"])
        if not raw:
            for item in self._bookmall_list(data):
                if isinstance(item, dict):
                    nested = item.get("video_data")
                    raw.extend(nested if isinstance(nested, list) else [item])
        videos = []
        for item in raw:
            vod = self._app_vod(item)
            if vod["vod_id"] and vod["vod_name"]:
                vod["style"] = {"type": "rect", "ratio": 0.67}
                videos.append(vod)
        root = data.get("data") or {}
        has_more = self._app_bool(root.get("has_more")) if isinstance(root, dict) else False
        result = {
            "page": page,
            "pagecount": page + 1 if has_more or len(videos) >= limit else page,
            "limit": limit,
            "total": len(videos),
            "list": videos,
        }
        self._actor_cache.set(cache_key, result)
        return result

    ACTOR_ID_KEYS = ("actor_id", "actorId", "celebrity_user_id", "celebrityUserId",
                     "celebrity_id", "celebrityId", "user_id", "userId", "uid")
    ACTOR_NAME_KEYS = ("actor_name", "actorName", "celebrity_name", "celebrityName",
                       "nickname", "nick_name", "user_name", "userName", "name")
    ACTOR_PIC_KEYS = ("avatar_url", "avatarUrl", "avatar", "user_avatar", "userAvatar", "head_url")

    @classmethod
    def _actor_str(cls, item, keys, numeric=False):
        for key in keys:
            value = item.get(key)
            if value is None or isinstance(value, (dict, list)):
                continue
            text = str(value).strip()
            if not text or text in ("0", "-1") or text.startswith("http"):
                continue
            if numeric and (not text.isdigit() or len(text) < 6):
                continue
            if not numeric and text.isdigit():
                continue
            return text
        return ""

    @classmethod
    def _actor_pic_of(cls, item):
        for key in cls.ACTOR_PIC_KEYS:
            value = item.get(key)
            if isinstance(value, str) and value.startswith("http"):
                return value.replace("\\/", "/")
            if isinstance(value, dict):
                for sub in ("url", "uri", "src"):
                    sub_value = value.get(sub)
                    if isinstance(sub_value, str) and sub_value.startswith("http"):
                        return sub_value.replace("\\/", "/")
        return ""

    def _actor_list(self, data):
        result, seen = [], set()
        for item in self._object_variants(data, max_depth=8):
            if not isinstance(item, dict):
                continue
            actor_id = self._actor_str(item, self.ACTOR_ID_KEYS, numeric=True)
            name = self._actor_str(item, self.ACTOR_NAME_KEYS)
            if not actor_id or not name or actor_id in seen:
                continue
            seen.add(actor_id)
            user_id = self._actor_str(item, ("user_id", "userId", "uid"), numeric=True)
            rank = ""
            for key in ("rank", "rank_num", "position"):
                value = item.get(key)
                if value and not isinstance(value, (dict, list)):
                    rank = str(value).strip()
                    break
            result.append({
                "vod_id": self._make_actor_id(actor_id, user_id or actor_id),
                "vod_name": name,
                "vod_pic": self._actor_pic_of(item) or self.RANK_HOME_PIC,
                "vod_remarks": rank,
                "vod_tag": "folder",
                "style": {"type": "oval"},
            })
        return result

    def _actor_rank_page(self, rank, page):
        config = next((item for item in self.ACTOR_RANK_CONFIG
                       if item["type_id"] == str(rank)), self.ACTOR_RANK_CONFIG[0])
        cache_key = "actor_rank|%s|%s" % (config["type_id"], page)
        cached = self._actor_cache.get(cache_key)
        if cached is not None:
            return cached
        limit = 18
        videos = []
        try:
            data = self._rank_request("ranklist_celebrity", config["selected"],
                                      (page - 1) * limit, limit)
            videos = self._actor_list(data)
            has_more = self._app_bool((data.get("data") or {}).get("has_more")) or len(videos) >= limit
        except Exception:
            has_more = False
        result = {
            "page": page, "pagecount": page + 1 if has_more else page,
            "limit": limit, "total": len(videos), "list": videos,
        }
        self._actor_cache.set(cache_key, result, ttl=20 if not videos else None)
        return result

    def _actor_works_feed(self, user_id, cursor=""):
        data = self._signed_app_post(
            f"https://api5-normal-sinfonlinea.fqnovel.com/novel/commentapi/user/profile/{quote(str(user_id))}/v1",
            {"klink_egdi": self.APP_KLINK_EGDI},
            {
                "comment_source": 1506,
                "count": 18,
                "cursor": str(cursor or ""),
                "extra_param": {},
                "locate_post_id": "",
                "profile_user_type": 0,
                "sort": "smart_hot_desc",
                "tab_type": 8,
                "target_user_id": str(user_id),
            },
        )
        root = data.get("data") if isinstance(data.get("data"), dict) else {}
        videos = self._actor_works(root)
        if not videos:
            videos = self._actor_works(data if isinstance(data, dict) else {})
        info = root.get("common_list_info")
        info = info if isinstance(info, dict) else {}
        highlight = root.get("hightlight") or root.get("highlight")
        highlight = highlight if isinstance(highlight, dict) else {}
        return videos, {
            "cursor": str(info.get("cursor") or ""),
            "has_more": self._app_bool(info.get("has_more")),
            "total": self._ok_int(highlight.get("total"), 0),
        }

    PIC_KEYS = ("cover_vertical", "series_cover", "cover", "cover_url", "pic", "image", "url")

    def _actor_works(self, data):
        result = []
        seen = set()
        for item in data.get("data_list") or []:
            if not isinstance(item, dict):
                continue
            source = item.get("video") if isinstance(item.get("video"), dict) else None
            if not source:
                source = item.get("subscribe_item") if isinstance(item.get("subscribe_item"), dict) else item
            source = source if isinstance(source, dict) else {}

            sid = str(source.get("series_id") or source.get("book_id")
                      or source.get("seriesId") or source.get("bookId")
                      or source.get("video_id") or "")
            if not sid.isdigit() or len(sid) < 6 or sid in seen:
                continue

            common = source.get("common") if isinstance(source.get("common"), dict) else {}
            name = self._safe_name(
                common.get("title") or
                source.get("series_name") or source.get("name") or ""
            )

            pic = ""
            for scope in (common, source, source.get("expand") if isinstance(source.get("expand"), dict) else {}):
                for key in self.PIC_KEYS:
                    if scope.get(key):
                        pic = str(scope[key]).replace("\\/", "/")
                        break
                if pic:
                    break
            if not pic:
                for obj in self._object_variants(source, max_depth=5):
                    if isinstance(obj, dict):
                        for key in self.PIC_KEYS:
                            val = obj.get(key)
                            if isinstance(val, str) and val.startswith("http"):
                                pic = val.replace("\\/", "/")
                                break
                        if pic:
                            break

            labels = []
            ep_remarks = ""
            expand = source.get("expand") if isinstance(source.get("expand"), dict) else {}
            sub_list = expand.get("sub_title_list") or source.get("sub_title_list") or []
            for sub in sub_list if isinstance(sub_list, list) else []:
                if isinstance(sub, dict):
                    text = str(sub.get("text") or sub.get("content") or "").strip()
                else:
                    text = str(sub or "").strip()
                if text:
                    if "集" in text:
                        ep_remarks = text
                    else:
                        labels.append(text)
            if not ep_remarks:
                ep_remarks = str(source.get("sub_info") or "").strip()
            if not ep_remarks:
                count = source.get("episode_cnt") or 0
                ep_remarks = f"全{count}集" if count else ""

            vod = {
                "vod_id": sid,
                "vod_name": name,
                "vod_pic": pic,
                "vod_remarks": ep_remarks,
                "vod_actor": "",
                "type_name": "/".join(labels[:5]),
                "vod_content": str(common.get("intro") or source.get("series_intro") or ""),
            }
            seen.add(sid)
            result.append(vod)

            if sid:
                self._app_item_cache[sid] = {
                    "series_id": sid,
                    "series_name": name,
                    "series_cover": pic,
                    "series_intro": vod["vod_content"],
                    "episode_right_text": ep_remarks,
                    "tags": [{"name": t} for t in labels],
                }
        return result

    def _actor_works_page(self, raw_id, page):
        raw = str(raw_id or "").split(":", 1)[-1]
        for sep in ("__", ":", "-"):
            if sep in raw:
                actor_id, user_id = raw.split(sep, 1)
                break
        else:
            actor_id, user_id = raw, ""
        user_id = user_id or actor_id
        limit = 18
        cache_key = "actor_works|%s|%s|%s" % (actor_id, user_id, page)
        cached = self._actor_cache.get(cache_key)
        if cached is not None:
            return cached

        state_key = "actor_works_state|%s|%s" % (actor_id, user_id)
        state = self._actor_cache.get(state_key) or {}
        items = list(state.get("items") or [])
        cursor = str(state.get("cursor") or "")
        has_more = bool(state.get("has_more", True))
        total = int(state.get("total") or 0)
        seen = {str(vod.get("vod_id") or "") for vod in items if isinstance(vod, dict)}

        while len(items) < page * limit and has_more:
            prev_cursor = cursor
            try:
                batch, feed = self._actor_works_feed(user_id, cursor)
            except Exception:
                has_more = False
                break
            added = 0
            for vod in batch:
                vid = str(vod.get("vod_id") or "")
                if vid and vid not in seen:
                    seen.add(vid)
                    items.append(vod)
                    added += 1
            cursor = str(feed.get("cursor") or "")
            total = max(total, int(feed.get("total") or 0), len(items))
            has_more = bool(feed.get("has_more"))
            if not added or cursor == prev_cursor:
                has_more = False
                break

        if not has_more:
            total = len(items)
        self._actor_cache.set(state_key, {"items": items, "cursor": cursor,
                                          "has_more": has_more, "total": total})
        result = self._ok_result({
            "page": page,
            "pagecount": max(1, (total + limit - 1) // limit) if total else page,
            "total": total,
            "list": items[(page - 1) * limit:page * limit],
        }, limit, page)
        self._actor_cache.set(cache_key, result)
        return result

    def homeContent(self, filter=False):
        try:
            with ThreadPoolExecutor(max_workers=2) as executor:
                catalog_future = executor.submit(self._catalog)
                list_future = executor.submit(self._distribution_page, "short_play", 1)
                catalog = catalog_future.result()
                first_page = list_future.result()
            classes = catalog.get("class") or self.CLASS_LIST
            filters = self._ok_filters(catalog.get("filters") or {})
            items = []
            for row in (first_page or {}).get("list") or []:
                vod = self._ok_vod(row)
                if vod:
                    items.append(vod)
            return {"class": classes, "filters": filters, "list": items}
        except Exception:
            return {"class": self.CLASS_LIST, "filters": {}, "list": []}

    def homeVideoContent(self):
        try:
            return self._ok_result(self._distribution_page("short_play", 1), 18, 1)
        except Exception:
            return self._ok_result({}, 18, 1)

    RANK_FOLDER_PREFIX = "rank_folder:"
    ACTOR_PREFIX = "actor:"
    FOLDER_SEP = "__"

    @staticmethod
    def _make_rank_folder_id(group_selected, sub_selected=""):
        return "rank_folder:%s__%s" % (group_selected or "", sub_selected or "")

    @staticmethod
    def _parse_rank_folder_id(type_id):
        parts = str(type_id or "").split(":", 1)[-1]
        for sep in ("__", "|", "-"):
            if sep in parts:
                group, sub = parts.split(sep, 1)
                return group, sub
        return parts, ""

    @staticmethod
    def _make_actor_id(actor_id, user_id=""):
        return "actor:%s__%s" % (actor_id or "", user_id or actor_id or "")

    def categoryContent(self, tid, pg, filter=False, extend=None):
        page = max(1, int(pg or 1)) if str(pg or "1").isdigit() else 1
        params = {}
        params.update(self._filter_values(filter))
        params.update(self._filter_values(extend))
        type_id = str(tid or "short_play")
        try:
            catalog = None
            if type_id.startswith("rank"):
                try:
                    catalog = self._catalog()
                except Exception:
                    pass
            if type_id in ("short_play", "comic_series", "ai_series"):
                return self._ok_result(self._distribution_page(type_id, page, params), 18, page)
            if type_id == "new_series":
                return self._ok_result(self._new_page(page, params), 18, page)
            if type_id == "rank_home":
                ranks = (catalog or {}).get("ranks", {})
                groups = ranks.get("groups", [])
                folder_list = []
                for group in groups:
                    group_name = str(group.get("name") or "")
                    for sub in group.get("sub", []):
                        sub_name = str(sub.get("name") or "")
                        plain = sub_name in ("", "全部", "总榜") or sub_name == group_name
                        folder_list.append({
                            "vod_id": self._make_rank_folder_id(group["selected"], sub.get("selected") or ""),
                            "vod_name": (group_name or sub_name or "榜单") if plain else sub_name,
                            "vod_pic": sub.get("pic") or group.get("pic") or self.RANK_HOME_PIC,
                            "vod_remarks": "" if plain else group_name,
                            "vod_tag": "folder",
                            "style": {"type": "list"},
                        })
                if not folder_list:
                    try:
                        fallback = self._new_page(page, {})
                        if fallback.get("list"):
                            return self._ok_result(fallback, 18, page)
                    except Exception:
                        pass
                    return self._ok_result({}, 18, page)
                total = len(folder_list)
                start = (page - 1) * 24
                end = min(start + 24, total)
                return self._ok_result({
                    "page": page,
                    "pagecount": max(1, (total + 23) // 24),
                    "total": total,
                    "list": folder_list[start:end],
                }, 24, page)
            if type_id.startswith(self.RANK_FOLDER_PREFIX):
                group_selected, sub_selected = self._parse_rank_folder_id(type_id)
                ranks = (catalog or {}).get("ranks", {})
                tmp_filters = {"rank_category": group_selected, "rank": sub_selected}
                return self._ok_result(self._rank_page(ranks, page, tmp_filters), 18, page)
            if type_id == "actor_home":
                rank = params.get("rank") or self.ACTOR_RANK_CONFIG[0]["type_id"]
                return self._ok_result(self._actor_rank_page(rank, page), 18, page)
            if type_id.startswith(self.ACTOR_PREFIX):
                return self._ok_result(self._actor_works_page(type_id, page), 18, page)
        except Exception:
            pass
        return self._ok_result({}, 18, page)

    def _app_search_params(self, word, tab_type, page, cursor=None, limit=None):
        cursor = cursor if isinstance(cursor, dict) else {}
        limit = max(1, int(limit or self.APP_SEARCH_PAGE_SIZE))
        offset = str(cursor.get("next_offset") or max(0, (page - 1) * limit))
        values = {
            "live_room_id": "0", "user_is_login": "0", "bookstore_tab": "16",
            "biz_config_ctx_infos": "", "last_book_id": str(cursor.get("last_book_id") or ""),
            "last_search_page_query": str(word), "clicked_content": "page_search_button",
            "report_info": "", "use_lynx": "false", "tab_type": str(tab_type),
            "last_book_consume_time": "0", "product_id": "0", "line_words_num": "0",
            "tab_name": "feed", "last_consume_interval": "0", "pad_column_cover": "0",
            "last_chapter_id": str(cursor.get("last_chapter_id") or ""), "only_feed": "false",
            "offset": offset, "from_rs": "false", "only_large_card": "false",
            "query": str(word), "count": "0", "target_main_id": "", "search_source": "1",
            "search_source_id": "clks###", "use_correct": "false",
            "last_search_page_interval": "0", "seed_product_id": "0",
            "from_half_screen": "false", "is_first_enter_search": "false",
            "corrected_query": "", "client_ab_info": json.dumps({
                "middle_style_from_video": False, "result_style_from_video": False,
            }, separators=(",", ":")),
            "bookshelf_search_plan": "4",
        }
        if cursor.get("search_id"):
            values["search_id"] = str(cursor["search_id"])
        if cursor.get("passback"):
            values["passback"] = str(cursor["passback"])
        return values

    @classmethod
    def _app_search_cells(cls, cell, depth=0):
        if not isinstance(cell, dict) or depth > 8:
            return []
        result = [cell]
        lynx = cell.get("lynx_data")
        if isinstance(lynx, str):
            try:
                lynx = json.loads(lynx)
            except Exception:
                lynx = None
        nested = lynx.get("cell_data") if isinstance(lynx, dict) else None
        if not isinstance(nested, list):
            nested = cell.get("cell_data")
        for item in nested if isinstance(nested, list) else []:
            result.extend(cls._app_search_cells(item, depth + 1))
        return result

    def _app_search_actor_vods(self, cell):
        if not isinstance(cell, dict):
            return []
        celebrities = cell.get("celebrity_user_list")
        if str(cell.get("show_type") or "") != "519" and not celebrities:
            return []
        rows = self._actor_list(celebrities or [])
        for row in rows:
            row.pop("style", None)
            row["vod_remarks"] = row.get("vod_remarks") or "演员"
        return rows

    @staticmethod
    def _app_search_tab_data(tab):
        value = tab.get("data") if isinstance(tab, dict) else None
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except Exception:
                return []
        if isinstance(value, list):
            return value
        if isinstance(value, dict) and isinstance(value.get("cell_data"), list):
            return value["cell_data"]
        return [value] if isinstance(value, dict) else []

    def _official_tab_page(self, word, page, limit, tab_type=11):
        page = max(1, int(page or 1))
        limit = max(1, int(limit or self.APP_SEARCH_PAGE_SIZE))
        cache_key = f"official_search|{tab_type}|{word}|{page}|{limit}"
        cached = self._cache.get(cache_key)
        if cached is not None:
            return cached
        cursor = {}
        if page > 1:
            previous = self._official_tab_page(word, page - 1, limit, tab_type)
            cursor = previous.get("cursor") or {}
            if not previous.get("has_more"):
                value = {"list": [], "has_more": False, "cursor": cursor}
                self._cache.set(cache_key, value)
                return value
        seen = set()
        result = []
        has_more = False
        for _ in range(3):
            data = self._signed_app_get(
                self.APP_SEARCH_API,
                self._app_search_params(word, tab_type, page, cursor, limit),
            )
            root = data.get("data") if isinstance(data.get("data"), dict) else {}
            tabs = data.get("search_tabs") or root.get("search_tabs") or []
            tab = next((x for x in tabs if isinstance(x, dict) and int(x.get("tab_type") or 0) == int(tab_type)), {})
            for cell in self._app_search_tab_data(tab):
                for item in self._app_search_cells(cell):
                    for actor in self._app_search_actor_vods(item):
                        if actor["vod_id"] not in seen:
                            seen.add(actor["vod_id"])
                            result.append(actor)
                    if str(item.get("show_type") or "") == "572":
                        continue
                    try:
                        vod, raw = self._app_search_vod(item, tab_type)
                        if vod and vod["vod_id"] not in seen:
                            seen.add(vod["vod_id"])
                            result.append(vod)
                            if raw:
                                self._app_item_cache[vod["vod_id"]] = raw
                    except Exception:
                        continue
            more_value = tab.get("has_more")
            if more_value is None:
                more_value = tab.get("hasMore")
            if more_value is None:
                more_value = data.get("has_more", root.get("has_more"))
            has_more = self._app_bool(more_value)
            cursor = {
                "search_id": str(tab.get("search_id") or data.get("search_id") or root.get("search_id") or ""),
                "passback": str(tab.get("passback") or data.get("passback") or root.get("passback") or ""),
                "next_offset": str(
                    tab.get("next_offset") if tab.get("next_offset") is not None
                    else data.get("next_offset") if data.get("next_offset") is not None
                    else root.get("next_offset") or ""
                ),
                "last_book_id": str(tab.get("last_book_id") or data.get("last_book_id") or root.get("last_book_id") or ""),
                "last_chapter_id": str(tab.get("last_chapter_id") or data.get("last_chapter_id") or root.get("last_chapter_id") or ""),
            }
            if result or not has_more:
                break
        page_data = {
            "list": result,
            "has_more": has_more,
            "cursor": cursor,
        }
        self._cache.set(cache_key, page_data)
        return page_data

    def _app_search_vod(self, cell, tab_type=11):
        videos = cell.get("video_data") or []
        if isinstance(videos, dict):
            video = videos
        else:
            video = next((x for x in videos if isinstance(x, dict)), {})
        highlight = cell.get("search_high_light") or {}
        title_info = highlight.get("title") or {}
        if int(tab_type or 11) in (1, 2, 21):
            return None, None

        if not self._is_short_drama(video):
            return None, None

        sid = str(video.get("series_id") or video.get("book_id") or cell.get("search_result_id") or "")
        name = str(title_info.get("text") or video.get("title") or cell.get("cell_name") or "").strip()
        pic = str(video.get("cover") or video.get("cover_url") or "")
        count = video.get("episode_cnt") or 0
        badge = self._extract_badge(video)
        collection = self._extract_collection(video)
        rec_text = self._extract_rec_text(video)
        actor = self._extract_actors(video)
        vod_remarks = f"全{count}集" if count else ""
        if not sid or not name:
            return None, None
        return {
            "vod_id": sid,
            "vod_name": name,
            "vod_pic": pic,
            "vod_remarks": vod_remarks,
            "vod_year": badge,
            "vod_actor": actor,
            "vod_extra": {
                "badge": badge,
                "collection": collection,
                "rec_text": rec_text
            }
        }, video

    def _app_item_for_series(self, series_id, title=""):
        series_id = str(series_id or "")
        cached = self._app_item_cache.get(series_id)
        if isinstance(cached, dict) and self._extract_actors(cached):
            return cached
        if title:
            try:
                self._official_tab_page(str(title), 1, self.APP_SEARCH_PAGE_SIZE, 11)
            except Exception:
                pass
        value = self._app_item_cache.get(series_id)
        return value if isinstance(value, dict) else (cached if isinstance(cached, dict) else {})

    @staticmethod
    def _app_detail_tags(series, collection=""):
        values = []
        for item in series.get("abstract_tags") or []:
            value = item.get("name") or item.get("content") if isinstance(item, dict) else item
            if value:
                values.append(str(value))
        for item in series.get("secondary_infos") or []:
            if isinstance(item, dict) and str(item.get("data_type") or "") == "3" and item.get("content"):
                values.append(str(item["content"]))
        schema = series.get("category_schema")
        if isinstance(schema, str):
            try:
                schema = json.loads(schema)
            except Exception:
                schema = []
        for item in schema if isinstance(schema, list) else []:
            if isinstance(item, dict) and item.get("name"):
                values.append(str(item["name"]))
        unique = list(dict.fromkeys(values))
        return "/".join(unique[:3])

    def detailContent(self, ids):
        request_id = str(ids[0]) if isinstance(ids, (list, tuple)) and ids else str(ids or "")
        series_id = request_id
        try:
            if not series_id.isdigit():
                raise RuntimeError("series_id invalid")
            series = hg_parser.get_long_video_detail(series_id)
            if not isinstance(series, dict) or not series:
                raise RuntimeError("APP detail empty")

            episodes = [item for item in series.get("video_list") or [] if isinstance(item, dict) and item.get("vid")]
            episodes.sort(key=lambda item: int(item.get("vid_index") or 0))
            clean_vids = [str(item["vid"]) for item in episodes]
            if not clean_vids:
                raise RuntimeError("APP detail missing video_list")
            for vid in clean_vids:
                self._episode_book_cache[vid] = series_id

            listing = self._app_item_for_series(series_id, series.get("series_title") or "")
            listing_detail = listing.get("video_detail") if isinstance(listing.get("video_detail"), dict) else {}

            content_type = series.get("content_type")
            is_comic_or_ai = content_type not in (1, 1004)

            celebrities = series.get("celebrities", [])
            actor_parts = []
            if celebrities:
                for celeb in celebrities:
                    if is_comic_or_ai:
                        role_name = celeb.get("role_name") or ""
                        if role_name:
                            actor_parts.append(role_name)
                    else:
                        nickname = celeb.get("nickname") or celeb.get("celebrity_name") or celeb.get("name") or ""
                        role_name = celeb.get("role_name") or ""
                        if nickname and role_name:
                            entry = f"{nickname}({role_name})"
                        elif nickname:
                            entry = nickname
                        else:
                            continue
                        actor_parts.append(entry)
                vod_actor = " / ".join(actor_parts)
            else:
                vod_actor = self._extract_actors(listing)

            rec_text = self._extract_rec_text(listing)
            collection = self._extract_collection(listing)
            badge = self._extract_badge(listing)

            count = series.get("episode_cnt") or len(clean_vids)
            remarks_parts = []
            app_subtitles = list(series.get("series_sub_title_list") or [])
            remark_values = [series.get("episode_right_text")] + app_subtitles
            if not app_subtitles:
                remark_values.append(rec_text)
            for value in remark_values:
                text = str(value or "").strip()
                if text and text not in remarks_parts:
                    remarks_parts.append(text)
            if not remarks_parts and count:
                remarks_parts.append("全%d集" % count)
            vod_remarks = " · ".join(remarks_parts)

            tracks = list(self.short_quality_tracks)
            play_from = "$$$".join(name for name, _ in tracks)
            play_urls = []
            for _, quality in tracks:
                play_urls.append("#".join(
                    "第%d集$%s" % (i + 1, self._encode_play_id(series_id, vid, quality))
                    for i, vid in enumerate(clean_vids)
                ))
            self._warmup_first_episode(clean_vids[0])
            item = self._ok_vod({
                "vod_id": request_id,
                "vod_name": str(series.get("series_title") or listing_detail.get("series_title") or listing.get("title") or "红果短剧"),
                "vod_pic": str(listing.get("cover") or listing_detail.get("series_cover") or series.get("series_cover") or "").replace("\\/", "/"),
                "type_name": self._app_detail_tags(series, collection),
                "vod_actor": vod_actor,
                "vod_remarks": vod_remarks,
                "vod_content": str(series.get("series_intro") or ""),
                "vod_play_from": play_from,
                "vod_play_url": "$$$".join(play_urls),
            })
            return {"list": [item] if item else []}
        except Exception:
            return {"list": []}

    @classmethod
    def _comment_text(cls, item):
        for value in cls._object_variants(item, max_depth=3):
            if not isinstance(value, dict):
                continue
            for key in ("content", "text", "comment_content", "comment_text", "text_content", "desc", "body"):
                candidate = value.get(key)
                if isinstance(candidate, dict):
                    candidate = candidate.get("text")
                if isinstance(candidate, (str, int, float)):
                    text = str(candidate).strip()
                    if text:
                        return text
        return ""

    @classmethod
    def _comment_time(cls, item):
        for value in cls._object_variants(item, max_depth=3):
            if not isinstance(value, dict):
                continue
            for key in ("video_offset_ms", "video_time_ms", "offset_time", "start_offset_time", "video_time", "comment_time", "position", "timestamp", "time"):
                try:
                    number = float(value.get(key))
                except (TypeError, ValueError):
                    continue
                if number < 0:
                    continue
                if key.endswith("_ms") or key in ("offset_time", "start_offset_time"):
                    return number / (1000000.0 if number > 1120000 else 1000.0)
                return number / 1000.0 if number > 1000000000 else number
        return 0.0

    @classmethod
    def _comment_cursor(cls, data):
        for value in cls._object_variants(data, max_depth=4):
            if not isinstance(value, dict):
                continue
            for key in ("cursor", "next_cursor", "nextCursor", "page_cursor"):
                cursor = str(value.get(key) or "").strip()
                if cursor:
                    return cursor
        return ""

    @classmethod
    def _comment_has_more(cls, data, rows, cursor):
        for value in cls._object_variants(data, max_depth=4):
            if not isinstance(value, dict):
                continue
            marker = value.get("has_more", value.get("hasMore"))
            if marker in (True, 1, "1"):
                return True
        return bool(cursor and rows)

    def _comment_rows(self, data):
        rows = []
        seen = set()
        items = self._response_array(data, ("comments", "comment_list", "commentList", "list", "danmaku", "danmus", "data_list", "items"))
        for index, item in enumerate(items):
            text = self._comment_text(item)
            if not text:
                continue
            comment_id = str(item.get("comment_id") or item.get("id") or item.get("cid") or item.get("commentId") or "%s|%s|%s" % (self._comment_time(item), text, index)) if isinstance(item, dict) else "%s|%s" % (text, index)
            if comment_id in seen:
                continue
            seen.add(comment_id)
            rows.append({"text": text, "time": self._comment_time(item)})
        return rows

    def _fetch_episode_danmaku(self, book_id, vid, max_pages=8):
        rows = []
        cursor = ""
        for _ in range(max_pages):
            payload = {
                "comment_source": 601, "server_channel": 1000, "group_id": str(vid), "group_type": 30,
                "comment_type": 20, "sort": 1,
                "business_param": {"book_id": str(book_id), "start_offset_time": 0, "playlet_item_duration": 112000, "need_danmaku_guide_type": [2]},
                "count": 90, "cursor": cursor, "aid": 8662, "compliance_status": 0,
            }
            data = self._signed_app_post(
                "%s/%s/v1/" % (self.APP_COMMENT_API, quote(str(vid))),
                {"klink_egdi": self.APP_KLINK_EGDI}, payload,
            )
            current = self._comment_rows(data)
            rows.extend(current)
            next_cursor = self._comment_cursor(data)
            if not self._comment_has_more(data, current, next_cursor) or not next_cursor or next_cursor == cursor:
                break
            cursor = next_cursor
        return rows

