    @staticmethod
    def _merge_comment_rows(rows):
        result = []
        seen = set()
        for row in sorted(rows, key=lambda item: float(item.get("time") or 0)):
            key = "%s|%s" % (row.get("time"), row.get("text"))
            if key not in seen:
                seen.add(key)
                result.append(row)
        return result

    @staticmethod
    def _comment_xml(rows):
        body = []
        for item in rows:
            timestamp = ("%.3f" % float(item.get("time") or 0)).rstrip("0").rstrip(".") or "0"
            body.append('<d p="%s,1,25,16777215,0">%s</d>' % (timestamp, html.escape(str(item.get("text") or ""), quote=True)))
        return '<?xml version="1.0" encoding="UTF-8"?><i>%s</i>' % "".join(body)

    def _finish_danmaku_cache(self, cache_key, book_id, vid):
        try:
            rows = []
            for fetcher in (
                lambda: self._fetch_episode_danmaku(book_id, vid, 8),
                lambda: self._fetch_episode_reviews(book_id, vid, 5),
                lambda: self._fetch_book_reviews(book_id, 32),
            ):
                try:
                    rows.extend(fetcher())
                except Exception:
                    continue
            if rows:
                self._danmaku_cache.set(cache_key, self._comment_xml(self._merge_comment_rows(rows)))
        finally:
            with self._danmaku_lock:
                self._danmaku_building.discard(cache_key)

    def _danmaku_xml(self, book_id, vid):
        cache_key = "%s|%s" % (book_id, vid)
        cached = self._danmaku_cache.get(cache_key)
        if cached is not None:
            return cached
        rows = []
        with ThreadPoolExecutor(max_workers=3) as pool:
            futures = (
                pool.submit(self._fetch_episode_danmaku, book_id, vid, 1),
                pool.submit(self._fetch_episode_reviews, book_id, vid, 1),
                pool.submit(self._fetch_book_reviews, book_id, 1),
            )
            for future in as_completed(futures):
                try:
                    rows.extend(future.result())
                except Exception:
                    continue
        if not rows:
            for fetcher in (
                lambda: self._fetch_episode_danmaku(book_id, vid, 1),
                lambda: self._fetch_episode_reviews(book_id, vid, 1),
                lambda: self._fetch_book_reviews(book_id, 1),
            ):
                try:
                    rows.extend(fetcher())
                except Exception:
                    continue
                if rows:
                    break
        xml = self._comment_xml(self._merge_comment_rows(rows))
        if rows:
            self._danmaku_cache.set(cache_key, xml)
        with self._danmaku_lock:
            if cache_key not in self._danmaku_building:
                self._danmaku_building.add(cache_key)
                threading.Thread(
                    target=self._finish_danmaku_cache,
                    args=(cache_key, str(book_id), str(vid)),
                    name="HongGuoDanmakuWarmup", daemon=True,
                ).start()
        return xml

    def playerContent(self, flag, pid, vipFlags=None):
        book_id, vid, quality = self._decode_play_id(pid)
        if not book_id:
            book_id = self._episode_book_cache.get(vid, "")
        quality = str(quality or flag or "auto").strip()
        proxy = self.getProxyUrl()
        joiner = "&" if "?" in proxy else "?"
        danmaku = ""
        if str(book_id).isdigit() and str(vid).isdigit():
            try:
                danmaku = _hg_register_danmaku(self, book_id, vid)
            except Exception:
                danmaku = proxy + joiner + urlencode({"mode": "danmaku", "book_id": str(book_id), "vid": str(vid)})
        try:
            video_url, content_key = self._resolve_stream_info(vid, quality)
            stream_url = hg_stream.register(video_url, content_key, hg_parser)
            result = {
                "parse": 0,
                "playUrl": "",
                "url": stream_url,
                "header": {"User-Agent": self.headers["User-Agent"]},
            }
            if danmaku:
                result["danmaku"] = danmaku
            return result
        except Exception:
            result = {
                "parse": 0,
                "playUrl": "",
                "url": proxy + joiner + "vid=" + quote(vid) + "&quality=" + quote(quality),
                "header": {"User-Agent": self.headers["User-Agent"]},
            }
            if danmaku:
                result["danmaku"] = danmaku
            return result

    def _warmup_first_episode(self, vid):
        def task():
            try:
                video_url, content_key = self._resolve_stream_info(str(vid), "video_5")
                hg_stream.warmup(video_url, content_key, hg_parser)
            except Exception:
                pass
        threading.Thread(target=task, name="HongGuoFirstEpisodeWarmup", daemon=True).start()

    def _resolve_stream_info(self, vid, quality="auto"):
        cached = hg_parser.get_cached_stream(vid, quality)
        if cached:
            return cached
        with self._video_lock:
            cached = hg_parser.get_cached_stream(vid, quality)
            if cached:
                return cached
            holder = {}
            original = hg_parser.download_decrypt_and_serve
            old_quality = getattr(hg_parser, "REQUESTED_QUALITY", "auto")
            def capture(request, video_url, content_key):
                holder["stream"] = (video_url, content_key)
                return "stream://" + str(vid)
            try:
                hg_parser.REQUESTED_QUALITY = str(quality or "auto")
                hg_parser.download_decrypt_and_serve = capture
                hg_parser.handle_video_request(str(vid), None, max_retries=2)
            finally:
                hg_parser.REQUESTED_QUALITY = old_quality
                hg_parser.download_decrypt_and_serve = original
            stream = holder.get("stream")
            if not stream or not stream[0] or not stream[1]:
                raise RuntimeError("stream empty")
            return stream

    def _resolve_video_bytes(self, vid, quality="auto"):
        cache_key = str(vid) + "|" + str(quality)
        cached = self._video_cache.get(cache_key)
        if cached is not None:
            return cached
        with self._video_lock:
            cached = self._video_cache.get(cache_key)
            if cached is not None:
                return cached
            holder = {}
            original = hg_parser.download_decrypt_and_serve
            def memory_pipeline(request, video_url, content_key):
                encrypted = hg_parser.download_video_bytes(video_url)
                holder["data"] = hg_parser.decrypt_video_bytes(encrypted, content_key)
                return "memory://" + vid
            old_quality = getattr(hg_parser, "REQUESTED_QUALITY", "auto")
            try:
                hg_parser.REQUESTED_QUALITY = str(quality or "auto")
                hg_parser.download_decrypt_and_serve = memory_pipeline
                stream = hg_parser.get_cached_stream(vid, quality)
                if stream:
                    memory_pipeline(None, stream[0], stream[1])
                else:
                    hg_parser.handle_video_request(vid, None, max_retries=2)
                data = holder.get("data")
                if not data:
                    raise RuntimeError("decrypt failed")
                self._video_cache.clear()
                self._video_cache.set(cache_key, data)
                return data
            finally:
                hg_parser.REQUESTED_QUALITY = old_quality
                hg_parser.download_decrypt_and_serve = original

    def localProxy(self, params):
        try:
            mode = str((params or {}).get("mode") or "").strip().lower()
            vid = str((params or {}).get("vid") or "").strip()
            if not vid.isdigit():
                return [400, "text/plain", b"vid invalid"]
            if mode == "danmaku":
                book_id = str((params or {}).get("book_id") or (params or {}).get("bookId") or "").strip()
                if not book_id.isdigit():
                    return [400, "text/plain", b"book_id invalid"]
                return [200, "text/xml; charset=utf-8", self._danmaku_xml(book_id, vid)]
            quality = str((params or {}).get("quality") or "auto").strip().lower().replace("p", "")
            data = self._resolve_video_bytes(vid, quality)
            return [200, "video/mp4", data]
        except Exception as exc:
            return [500, "text/plain", ("播放失败：" + str(exc)).encode("utf-8")]

    def searchContent(self, key, quick=False, pg=1):
        page = max(1, int(pg or 1)) if str(pg or "1").isdigit() else 1
        word = str(key or "").strip()
        if not word:
            return self._ok_result({}, self.APP_SEARCH_PAGE_SIZE, page)
        try:
            current = self._official_tab_page(word, page, self.APP_SEARCH_PAGE_SIZE, 11)
            has_more = bool(current.get("has_more"))
            return self._ok_result({
                "list": current.get("list") or [],
                "page": page,
                "pagecount": page + 1 if has_more else page,
                "total": 0,
            }, self.APP_SEARCH_PAGE_SIZE, page)
        except Exception:
            return self._ok_result({}, self.APP_SEARCH_PAGE_SIZE, page)

    def searchContentPage(self, key, quick=False, pg=1):
        return self.searchContent(key, quick, pg)